# Simple map format
# MAP <mapId>
# GROUND <defaultSpritePath>
# OBJECT <id> <type> <x> <y> <spritePath> solid=<0|1>
# TRIGGER <id> <x> <y> <width> <height> <eventName> [glow=0|1] [spawn_x=<x> spawn_y=<y>]

MAP 0001_TestMap
GROUND Assets/Sprites/Environment/Forest/forest_ground.png

OBJECT rock_01 scenery -192 -64 Assets/Sprites/Environment/Forest/forest_rock.png solid=1
OBJECT rock_02 scenery -128 -64 Assets/Sprites/Environment/Forest/forest_rock.png solid=1
OBJECT rock_03 scenery 64 -128 Assets/Sprites/Environment/Forest/forest_rock.png solid=1
OBJECT rock_04 scenery 192 -64 Assets/Sprites/Environment/Forest/forest_rock.png solid=1
OBJECT rock_05 scenery -192 128 Assets/Sprites/Environment/Forest/forest_rock.png solid=1
OBJECT rock_06 scenery -64 128 Assets/Sprites/Environment/Forest/forest_rock.png solid=1
OBJECT rock_07 scenery 128 128 Assets/Sprites/Environment/Forest/forest_rock.png solid=1
OBJECT rock_08 scenery 256 192 Assets/Sprites/Environment/Forest/forest_rock.png solid=1

TRIGGER spawn_area -80 -80 160 160 Trigger_SpawnArea
TRIGGER magic_sparkle 288 -32 64 64 magic_sparkle glow=1
TRIGGER magic_fire 448 -32 64 64 magic_fire glow=1
TRIGGER magic_lightning 608 -32 64 64 magic_lightning glow=1
TRIGGER magic_frost 768 -32 64 64 magic_frost glow=1
TRIGGER magic_vortex 928 -32 64 64 magic_vortex glow=1
TRIGGER magic_heal 1088 -32 64 64 magic_heal glow=1
TRIGGER magic_shockwave 1248 -32 64 64 magic_shockwave glow=1
TRIGGER north_path_to_forest -64 -260 220 120 Load_0001_Forest glow=1 spawn_x=-128 spawn_y=1024
